export interface Parcel {
  id: string;
  recipient: string;
  units: number;
  massKg: number;
}

export type ParcelPatch = Partial<Omit<Parcel, "id">>;

function validate(parcel: Parcel): void {
  if (parcel.id.trim().length === 0 || parcel.recipient.trim().length === 0) throw new RangeError("blank field");
  if (!Number.isSafeInteger(parcel.units) || parcel.units < 0) throw new RangeError("invalid units");
  if (!Number.isFinite(parcel.massKg) || parcel.massKg < 0) throw new RangeError("invalid mass");
}

export class ParcelLedger {
  private readonly records = new Map<string, Parcel>();

  constructor(initial: readonly Parcel[] = []) {
    for (const parcel of initial) this.create(parcel);
  }

  create(parcel: Parcel): void {
    validate(parcel);
    if (this.records.has(parcel.id)) throw new RangeError("duplicate id");
    this.records.set(parcel.id, { ...parcel });
  }

  get(id: string): Parcel {
    const parcel = this.records.get(id);
    if (!parcel) throw new RangeError("unknown id");
    return { ...parcel };
  }

  list(): Parcel[] {
    return Array.from(this.records.values(), (parcel) => ({ ...parcel }));
  }

  update(id: string, patch: ParcelPatch): Parcel {
    const current = this.records.get(id);
    if (!current) throw new RangeError("unknown id");
    const next: Parcel = {
      id,
      recipient: patch.recipient ?? current.recipient,
      units: patch.units ?? current.units,
      massKg: patch.massKg || current.massKg,
    };
    validate(next);
    this.records.set(id, next);
    return { ...next };
  }

  remove(id: string): boolean {
    return this.records.delete(id);
  }
}

