import * as S from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const initial = [
  { id: ' p1 ', recipient: ' Alice ', units: 0, massKg: 0 },
  { id: 'p2', recipient: 'Bob', units: 2, massKg: 1.25 }
];
const ledger = new S.ParcelLedger(initial as readonly S.Parcel[]);
initial[0].recipient = 'changed';
equal(ledger.get(' p1 ').recipient, ' Alice ', 'constructor copies input and preserves whitespace');
deepEqual(ledger.list().map((parcel) => parcel.id), [' p1 ', 'p2'], 'constructor preserves order');

const created = { id: 'p3', recipient: 'Cara', units: 3, massKg: 4.5 };
ledger.create(created as S.Parcel);
created.recipient = 'changed';
deepEqual(ledger.list().map((parcel) => parcel.id), [' p1 ', 'p2', 'p3'], 'create appends');
equal(ledger.get('p3').recipient, 'Cara', 'create copies input');

const fetched = ledger.get('p3');
fetched.recipient = 'caller';
equal(ledger.get('p3').recipient, 'Cara', 'get returns a copy');
const listed = ledger.list();
listed[0].recipient = 'caller';
listed.pop();
equal(ledger.get(' p1 ').recipient, ' Alice ', 'list returns deep copies');
equal(ledger.list().length, 3, 'list array mutation is isolated');
assert(ledger.get('p3') !== ledger.get('p3'), 'get allocates each result');
assert(ledger.list() !== ledger.list(), 'list allocates each array');
assert(ledger.list()[0] !== ledger.list()[0], 'list allocates each parcel');

const patch = { recipient: ' Updated ', units: 0, massKg: 0 };
ledger.update('p2', patch as S.ParcelPatch);
patch.recipient = 'changed';
const updated = ledger.get('p2');
equal(updated.recipient, ' Updated ', 'recipient update preserves whitespace');
equal(updated.units, 0, 'update accepts zero units');
equal(updated.massKg, 0, 'update accepts zero mass');
deepEqual(ledger.list().map((parcel) => parcel.id), [' p1 ', 'p2', 'p3'], 'update preserves creation order');
ledger.update('p2', {});
deepEqual(ledger.get('p2'), updated, 'empty patch is valid and preserves values');

throwsRange(() => ledger.create({ id: 'p2', recipient: 'duplicate', units: 1, massKg: 1 } as S.Parcel), 'duplicate ID');
throwsRange(() => ledger.get('missing'), 'unknown get');
throwsRange(() => ledger.update('missing', {}), 'unknown update');
for (const parcel of [
  { id: ' ', recipient: 'x', units: 1, massKg: 1 },
  { id: 'x', recipient: '\t', units: 1, massKg: 1 },
  { id: 'x', recipient: 'x', units: -1, massKg: 1 },
  { id: 'x', recipient: 'x', units: 1.5, massKg: 1 },
  { id: 'x', recipient: 'x', units: Number.MAX_SAFE_INTEGER + 1, massKg: 1 },
  { id: 'x', recipient: 'x', units: 1, massKg: -1 },
  { id: 'x', recipient: 'x', units: 1, massKg: Number.NaN },
  { id: 'x', recipient: 'x', units: 1, massKg: Number.POSITIVE_INFINITY }
]) {
  throwsRange(() => ledger.create(parcel as S.Parcel), 'malformed parcel');
}
throwsRange(() => ledger.update('p3', { recipient: '  ' }), 'blank patched recipient');
throwsRange(() => ledger.update('p3', { units: -1 }), 'negative patched units');
throwsRange(() => ledger.update('p3', { massKg: Number.POSITIVE_INFINITY }), 'nonfinite patched mass');
throwsRange(() => new S.ParcelLedger([
  { id: 'same', recipient: 'A', units: 0, massKg: 0 },
  { id: 'same', recipient: 'B', units: 0, massKg: 0 }
] as readonly S.Parcel[]), 'constructor duplicate IDs');

equal(ledger.remove('missing'), false, 'remove unknown returns false');
equal(ledger.remove('p2'), true, 'remove existing returns true');
equal(ledger.remove('p2'), false, 'removed ID is absent');
deepEqual(ledger.list().map((parcel) => parcel.id), [' p1 ', 'p3'], 'remove preserves remaining order');

